        "x": {
          "field": "Ordinary Beds per 1,000 Residents",
          "type": "quantitative",
          "scale": {
            "zero": false
          }
        },
        "color": {
          "field": "year",
          "type": "nominal",
          "title": "Year",
          "scale": {
            "domain": [
              2021,
              2023
            ],
            "range": [
              "#2a78d6",
              "#eb6834"
